/// <summary>
/// Generic class for processing transfered D365 records over API
/// </summary>
internal final class NDXTableTransferAPI
{
}

Method.Source:
/// <summary>
/// transferTableRecord
/// </summary>
/// <param name = "_tableRecord">rocord json format</param>
/// <returns>request response</returns>
public NDXTableTransferAPIResponse transferTableRecord(str _tableRecord)
{
    System.Exception ex;
    Niedax.AX.TableRecordModels.TableRecord tableRecord;
    Niedax.D365.API.Models.D365_APIResponse csResponse;

    DictClass dictClass;
    Object object;

    NDXTableTransferAPIResponse response = new NDXTableTransferAPIResponse();
    response.parmSuccess(false);

    tableRecord = Niedax.AX.TableRecordModels.TableRecord::Deserialize(_tableRecord);

    try
    {
        if(tableRecord != null && tableRecord.D365ClassName != '')
        {
            dictClass = new DictClass(className2Id(tableRecord.D365ClassName));
            object = dictClass.makeObject();
            csResponse = dictClass.callObject('writeRecord', object, tableRecord);
        }

        if(csResponse !=  null)
        {
            response.parmRecId(csResponse.RecId);
            response.parmSuccess(csResponse.Success);
            response.parmMessage(csResponse.Message);
        }
    }
    catch(ex)
    {
        response.parmMessage(ex.Message);
    }

    return response;
}
